const KEY={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right'};
const NATIVE='input,textarea,select,button,a,[role="button"],[contenteditable="true"]';
/** The court owns direction events only. Global E/Escape/R/M retain their owner. */
export function mountBumperInput({stage,ride,walking,isAllowed=()=>true,onChange=()=>{},showDirections=true,controlsClass='bumper-controls',getExternalIntent=null,scopeSelector=null,useDrivingStick=false}){
 const doc=stage.ownerDocument??document,win=doc.defaultView??window,element=doc.createElement('section');element.className=controlsClass;element.tabIndex=0;element.setAttribute('role','group');element.setAttribute('aria-label','범퍼카 운전 · 방향키 또는 W A S D');element.setAttribute('data-bumper-native','');
 const directions=['up','left','down','right'],labels=['앞으로','왼쪽','브레이크 · 뒤로','오른쪽'],symbols=['↑','←','↓','→'],buttons=[],keys=new Set(),held=new Set(),nativeHeld=new Set(),pointers=new Map(),listeners=[];
 let alive=true,pulse='',pulseTime=0,pendingLeave=false,status='';
 const listen=(node,type,fn,capture=false)=>{node?.addEventListener?.(type,fn,capture);listeners.push([node,type,fn,capture]);};
 const allowed=()=>alive&&isAllowed()&&!doc.hidden&&doc.hasFocus?.()!==false;
 const scope=node=>element.contains(node)||!!node?.closest?.('#activity-note,#activity-guide,#activity-close,#action')||!!(scopeSelector&&node?.closest?.(scopeSelector));
 function intent(){let up=false,down=false,left=false,right=false;for(const key of keys){const d=KEY[key];up||=d==='up';down||=d==='down';left||=d==='left';right||=d==='right';}for(const value of pointers.values()){up||=value.dir==='up';down||=value.dir==='down';left||=value.dir==='left';right||=value.dir==='right';}up||=pulse==='up';down||=pulse==='down';left||=pulse==='left';right||=pulse==='right';let throttle=Number(up)-Number(down),steer=Number(right)-Number(left);const external=getExternalIntent?.();if(external&&Number.isFinite(external.x)&&Number.isFinite(external.z)&&(Math.abs(external.x)>1e-9||Math.abs(external.z)>1e-9)){throttle=external.z;steer=external.x;}ride.setIntent(throttle,steer);}
 function paint(){if(!alive)return;const next=(ride.exitRequested?8:0)+(ride.paused?4:0)+(ride.phase==='entering'?1:ride.phase==='exiting'?2:3);if(next===status)return;status=next;pauseButton.textContent=ride.paused?'계속하기':'잠깐 멈춤';pauseButton.setAttribute('aria-pressed',String(ride.paused));element.setAttribute('aria-label',ride.paused?'범퍼카 일시 정지 · 계속하기를 눌러요':ride.exitRequested?'출발 자리로 돌아가는 중':'범퍼카 운전 · 방향키 또는 W A S D');onChange();}
 function release(id){const old=pointers.get(id);if(!old)return;pointers.delete(id);try{if(old.button.hasPointerCapture?.(id))old.button.releasePointerCapture(id);}catch{}let used=false;for(const p of pointers.values())if(p.button===old.button)used=true;if(!used)old.button.classList.remove('is-pressed');intent();}
 function clear(){keys.clear();pulse='';pulseTime=0;for(const id of pointers.keys())release(id);for(const button of buttons)button.classList.remove('is-pressed');ride.setIntent(0,0);walking?.clear();}
 function pause(){if(!alive)return;if(!ride.paused){clear();if(useDrivingStick)walking?.setDrivingStickEnabled?.(false);ride.pause();}paint();}
 function resume(){if(!allowed())return false;clear();ride.resume();element.focus({preventScroll:true});paint();return true;}
 for(let i=0;showDirections&&i<directions.length;i++){const dir=directions[i],button=doc.createElement('button');button.type='button';button.className='bumper-'+dir;button.textContent=symbols[i];button.setAttribute('data-bumper-direction',dir);button.setAttribute('aria-label',labels[i]);element.append(button);buttons.push(button);
  listen(button,'pointerdown',e=>{if(!alive||!allowed()||ride.paused||ride.phase!=='active'||ride.exitRequested||e.button!==0||pointers.has(e.pointerId))return;e.preventDefault();element.focus({preventScroll:true});pointers.set(e.pointerId,{dir,button});try{button.setPointerCapture(e.pointerId);}catch{release(e.pointerId);return;}button.classList.add('is-pressed');intent();});
  for(const type of['pointerup','pointercancel','lostpointercapture'])listen(button,type,e=>{if(alive)release(e.pointerId);});
  listen(button,'pointermove',e=>{if(!alive||!pointers.has(e.pointerId))return;const r=button.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)release(e.pointerId);});
  listen(button,'keydown',e=>{if(!alive||!['Space','Enter'].includes(e.code))return;e.preventDefault();e.stopPropagation();if(e.repeat||nativeHeld.has(e.code))return;nativeHeld.add(e.code);if(allowed()&&!ride.paused&&!ride.exitRequested){pulse=dir;pulseTime=.12;intent();}});
  listen(button,'click',e=>{if(!alive||e.detail!==0||nativeHeld.size||pulseTime>0||!allowed()||ride.paused||ride.exitRequested)return;pulse=dir;pulseTime=.12;intent();});
 }
 const pauseButton=doc.createElement('button');pauseButton.type='button';pauseButton.className='bumper-pause';pauseButton.setAttribute('data-bumper-pause','');element.append(pauseButton);listen(pauseButton,'click',()=>{if(ride.paused)resume();else pause();});
 listen(doc,'keydown',e=>{if(!alive||e.ctrlKey||e.metaKey||e.altKey)return;if(['KeyR','KeyM','BracketLeft','BracketRight'].includes(e.code)){if(!e.target?.closest?.('input,textarea,select,[contenteditable="true"]'))pause();return;}if(!KEY[e.code])return;const first=!held.has(e.code);held.add(e.code);if(e.target?.isContentEditable||e.target?.closest?.(NATIVE))return;if(!allowed()||ride.paused||ride.exitRequested)return;e.preventDefault();e.stopPropagation();if(e.repeat||!first||ride.phase!=='active')return;keys.add(e.code);intent();},true);
 listen(doc,'keyup',e=>{held.delete(e.code);nativeHeld.delete(e.code);if(keys.delete(e.code))intent();},true);
 listen(doc,'focusin',e=>{if(alive&&!scope(e.target))pause();});
 listen(doc,'pointerdown',e=>{if(alive&&!scope(e.target))pause();},true);
 listen(doc,'click',e=>{if(alive&&e.target?.closest?.('#hud-menu,#activity-guide,#activity-close')){pause();onChange();}});
 listen(doc,'wheel',e=>{if(alive&&!scope(e.target))pause();},true);
 listen(win,'blur',pause);listen(win,'orientationchange',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});
 if(useDrivingStick)walking?.setDrivingStickEnabled?.(true);stage.setAttribute('data-vehicle-stick-active',String(!!useDrivingStick));stage.setAttribute('data-bumper-active','true');stage.append(element);element.focus({preventScroll:true});paint();
 return{element,pause,resume(){const result=allowed();if(!result)return false;if(useDrivingStick&&!ride.exitRequested)walking?.setDrivingStickEnabled?.(true);clear();ride.resume();element.focus({preventScroll:true});paint();return true;},leave(){clear();if(useDrivingStick)walking?.setDrivingStickEnabled?.(false);pendingLeave=!allowed();if(!pendingLeave)ride.resume();paint();},sync(dt=0){if(!alive)return;if(!allowed()){pause();return;}if(pendingLeave){pendingLeave=false;ride.resume();}if(pulseTime>0){pulseTime=Math.max(0,pulseTime-(Number.isFinite(dt)?Math.max(0,dt):0));if(pulseTime===0){pulse='';intent();}}intent();paint();},dispose(){if(!alive)return;clear();ride.pause();alive=false;for(const[node,type,fn,capture]of listeners)node?.removeEventListener?.(type,fn,capture);listeners.length=0;held.clear();nativeHeld.clear();element.remove();stage.setAttribute('data-vehicle-stick-active','false');stage.setAttribute('data-bumper-active','false');if(useDrivingStick)walking?.setDrivingStickEnabled?.(false);onChange();}};
}
